fn check_all_lowercase(v: &Vec<char>) -> bool {
    // Input must be non-empty and every character must be a lowercase ASCII letter.
    if v.is_empty() {
        return false;
    }
    v.iter().all(|&c| c.is_ascii_lowercase())
}

fn solve(input: Vec<char>) -> Vec<char> {
    // If and only if all letters are lowercase (and input is non-empty), return ['a'], otherwise ['A'].
    if check_all_lowercase(&input) {
        vec!['a']
    } else {
        vec!['A']
    }
}

// Example usage and quick test
fn main() {
    let cases = vec![
        (vec!['h', 'e', 'l', 'l', 'o'], "all lowercase"),
        (vec!['H', 'i'], "contains uppercase"),
        (vec![], "empty"),
        (vec!['a', 'z', 'm'], "all lowercase"),
        (vec!['a', 'Z', 'm'], "mixed"),
    ];

    for (input, description) in cases {
        let result = solve(input.clone());
        println!("{:?} ({}) -> {:?}", input, description, result);
    }
}